{"perguntas":[
 {"t":"multipla","p":"O que os falsos mestres introduziriam dissimuladamente?","o":["Novas leis sobre o sábado","Heresias destrutivas","Ídolos de ouro","Sacrifícios estrangeiros"],"c":1,"v":1,"e":"O versículo 1 diz que os falsos mestres introduziriam, dissimuladamente, heresias destrutivas."},
 {"t":"multipla","p":"Quem Deus preservou quando trouxe o dilúvio, chamado de pregador da justiça?","o":["Noé","Abraão","Enoque","Moisés"],"c":0,"v":5,"e":"O versículo 5 diz que Deus preservou Noé, pregador da justiça, e mais sete pessoas."},
 {"t":"multipla","p":"Por que Ló se sentia angustiado?","o":["Pela perda de seus bens","Pela ameaça de uma guerra","Pela conduta libertina daqueles insubordinados","Pela fome na terra"],"c":2,"v":7,"e":"O versículo 7 diz que Ló se sentia angustiado pela conduta libertina daqueles insubordinados."},
 {"t":"multipla","p":"Segundo o capítulo, o que o Senhor sabe fazer com os piedosos?","o":["Dar-lhes riquezas","Torná-los profetas","Afastá-los do mundo","Livrá-los da provação"],"c":3,"v":9,"e":"O versículo 9 diz que o Senhor sabe livrar os piedosos da provação."},
 {"t":"multipla","p":"Os falsos mestres se desviaram seguindo o caminho de quem?","o":["Caim","Balaão, filho de Beor","Coré","Jeroboão"],"c":1,"v":15,"e":"O versículo 15 diz que eles seguiram o caminho de Balaão, filho de Beor, que amou a recompensa da injustiça."},
 {"t":"cv","p":"Os falsos mestres são comparados a fontes sem água e a nuvens levadas por tempestade.","c":true,"v":17,"e":"O versículo 17 diz que eles são como fontes sem água, como nuvens levadas por tempestade."},
 {"t":"cv","p":"Os falsos mestres prometem liberdade e eles mesmos estão livres da corrupção.","c":false,"v":19,"e":"O versículo 19 diz que eles prometem liberdade, mas eles próprios são escravos da corrupção."},
 {"t":"cv","p":"O capítulo termina citando o ditado sobre o cão que voltou ao seu próprio vômito e a porca lavada que voltou ao lamaçal.","c":true,"v":22,"e":"O versículo 22 traz o ditado do cão que voltou ao vômito e da porca lavada que voltou a revolver-se no lamaçal."}
]}

2 Pedro 3 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O que os escarnecedores dos últimos dias perguntam?","o":["Onde estão os santos profetas?","Onde está a promessa de sua vinda?","Por que devemos nos arrepender?","Quem escreveu esta carta?"],"c":1,"v":4,"e":"No versículo 4, os escarnecedores perguntam: \"Onde está a promessa de sua vinda?\""},
 {"t":"multipla","p":"Como pereceu o mundo daquela época?","o":["Consumido pelo fogo","Destruído por um terremoto","Submerso nas águas do dilúvio","Abatido pela fome"],"c":2,"v":6,"e":"O versículo 6 diz que o mundo daquela época pereceu submerso nas águas do dilúvio."},
 {"t":"multipla","p":"Para o Senhor, um dia é como quanto tempo?","o":["Cem anos","Mil anos","Uma hora","Sete anos"],"c":1,"v":8,"e":"O versículo 8 diz que para o Senhor um dia é como mil anos, e mil anos, como um dia."},
 {"t":"multipla","p":"Por que o Senhor é longânimo?","o":["Porque ainda não decidiu o dia","Porque espera os profetas","Porque não deseja que ninguém pereça","Porque os céus ainda não estão prontos"],"c":2,"v":9,"e":"O versículo 9 diz que o Senhor é longânimo, não desejando que ninguém pereça, mas que todos cheguem ao arrependimento."},
 {"t":"multipla","p":"Como virá o dia do Senhor?","o":["Como um ladrão à noite","Como a chuva da manhã","Como um rei com seu exército","Como o sol ao meio-dia"],"c":0,"v":10,"e":"O versículo 10 diz que o dia do Senhor virá como um ladrão à noite."},
 {"t":"cv","p":"Segundo a promessa, esperamos novos céus e nova terra, onde habita a justiça.","c":true,"v":13,"e":"O versículo 13 diz que, segundo a sua promessa, esperamos novos céus e nova terra, onde habita a justiça."},
 {"t":"cv","p":"Pedro diz que todas as passagens das cartas de Paulo são fáceis de compreender.","c":false,"v":16,"e":"O versículo 16 diz que nas cartas de Paulo há algumas passagens difíceis de compreender."},
 {"t":"cv","p":"O capítulo termina pedindo que os leitores cresçam na graça e no conhecimento de nosso Senhor e Salvador Jesus Cristo.","c":true,"v":18,"e":"O versículo 18 pede: \"cresçam na graça e no conhecimento de nosso Senhor e Salvador Jesus Cristo\"."}
]}

2 Pedro 1 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Como Pedro se apresenta no início da carta?","o":["Servo e apóstolo de Jesus Cristo","Presbítero e pastor da igreja","Profeta e mestre de Israel","Discípulo e irmão do Senhor"],"c":0,"v":1,"e":"No versículo 1, ele se apresenta como Simão Pedro, servo e apóstolo de Jesus Cristo."},
 {"t":"multipla","p":"Para que Deus concedeu suas preciosas e grandes promessas?","o":["Para que governemos sobre as nações","Para que sejamos coparticipantes da natureza divina","Para que recebamos riquezas na terra","Para que entendamos todos os mistérios"],"c":1,"v":4,"e":"O versículo 4 diz que as promessas foram dadas para que sejamos coparticipantes da natureza divina, escapando da corrupção do mundo."},
 {"t":"multipla","p":"O que Pedro manda acrescentar primeiro à fé?","o":["O amor","A perseverança","A virtude","O domínio próprio"],"c":2,"v":5,"e":"No versículo 5, Pedro pede que acrescentem à fé a virtude e, à virtude, o conhecimento."},
 {"t":"multipla","p":"Como Pedro descreve quem não possui essas qualidades?","o":["Como fraco, mas ainda em crescimento","Como alguém que nunca creu","Como servo infiel que será castigado","Como cego, vendo apenas o que está próximo"],"c":3,"v":9,"e":"O versículo 9 diz que quem não as possui é cego, vê apenas o que está próximo e se esqueceu da purificação de seus pecados antigos."},
 {"t":"multipla","p":"Onde Pedro diz que ouviu a voz que veio do céu?","o":["No templo de Jerusalém","No monte santo","Às margens do rio Jordão","No mar da Galileia"],"c":1,"v":18,"e":"No versículo 18, Pedro diz que ouviram a voz enquanto estavam com Jesus no monte santo."},
 {"t":"cv","p":"Pedro diz que, quem se esforça para confirmar sua vocação e eleição, nunca tropeçará.","c":true,"v":10,"e":"O versículo 10 afirma que, agindo assim, eles nunca tropeçarão em tempo algum."},
 {"t":"cv","p":"Pedro afirma que anunciou a vinda de Cristo com base em relatos que ouviu de outras pessoas.","c":false,"v":16,"e":"No versículo 16, Pedro diz que ele e os outros foram testemunhas oculares da majestade de Cristo."},
 {"t":"cv","p":"Segundo Pedro, a profecia foi produzida pela vontade humana.","c":false,"v":21,"e":"O versículo 21 diz que a profecia nunca veio da vontade humana: homens santos de Deus falaram movidos pelo Espírito Santo."}
]}
